$sql="SELECT public_id id,COALESCE(first_name,'') firstName,COALESCE(last_name,'') lastName,name fullName,email,COALESCE(company_name,company,'') companyName,COALESCE(phone,'') phone,COALESCE(job_title,'') jobTitle,COALESCE(website,'') website,COALESCE(linkedin,'') linkedin,COALESCE(facebook,'') facebook,COALESCE(instagram,'') instagram,COALESCE(twitter,'') twitter,COALESCE(tiktok,'') tiktok,other_socials otherSocialLinks,COALESCE(location,'') location,COALESCE(country,'') country,COALESCE(source,'') source,custom_fields customFields,status,tags,COALESCE(notes,'') notes,created_at createdAt,updated_at updatedAt FROM leads WHERE tenant_id=? AND public_id=?";$p=[$u['tenant_id'],$id];
